-- Validated reference configuration refinements, multi-shot and lip sync.
on conflict (key) do update set name=excluded.name, provider=excluded.provider, provider_model_id=excluded.provider_model_id, media_type=excluded.media_type, credit_cost=excluded.credit_cost, provider_credit_cost=excluded.provider_credit_cost, description=excluded.description, badge=excluded.badge, parameter_schema=excluded.parameter_schema, provider_config=excluded.provider_config, credit_rules=excluded.credit_rules, is_active=excluded.is_active, sort_order=excluded.sort_order;
update storage.buckets set allowed_mime_types = array_append(allowed_mime_types,'audio/wav') where id='studio-inputs' and not ('audio/wav'=any(allowed_mime_types));
